import fcntl, os, pty, signal, sys, termios, time
master, slave = pty.openpty()
name = os.ttyname(slave).removeprefix('/dev/')
ready_r, ready_w = os.pipe()
pid = os.fork()
if pid == 0:
    os.close(ready_r); os.setsid(); fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
    for fd in (0, 1, 2): os.dup2(slave, fd)
    if sys.argv[1] == 'closed':
        for fd in (0, 1, 2): os.close(fd)
    os.write(ready_w, b'1'); os.close(ready_w)
    while True: time.sleep(1)
os.close(ready_w)
if os.read(ready_r, 1) != b'1': raise SystemExit(1)
stop = False
def term(sig, frame):
    global stop
    stop = True
signal.signal(signal.SIGTERM, term)
with open('tty-info', 'w') as out: print(pid, name, file=out)
try:
    while not stop: time.sleep(.1)
finally:
    os.kill(pid, signal.SIGKILL); os.waitpid(pid, 0); os.close(master); os.close(slave)
